fn main() {
    input!{
        N: usize,
        M: usize,
        edges: [(usize1, usize1); M],
    }

    let mut union_find = UnionFind {
        parent: (0..N).collect(),
        size: vec![1; N],
    };


    let mut closed = N*(N-1)/2;
    let mut output: Vec<usize> = Vec::with_capacity(M);

    for (a, b) in edges.into_iter().rev() {
        output.push(closed);
        let root_a = union_find.root(a);
        let root_b = union_find.root(b);
        if root_a != root_b {
            closed -= union_find.size[root_b] * union_find.size[root_a];
            union_find.parent[root_a] = root_b;
            union_find.size[root_b] += union_find.size[root_a];
        }
    }

    for c in output.into_iter().rev() {
        println!("{}", c);
    }
}

struct UnionFind {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl UnionFind {
    fn root(&mut self, v: usize) -> usize {
        let mut parent_v = self.parent[v];
        loop {
            if parent_v == self.parent[parent_v] {
                break;
            } else {
                parent_v = self.parent[parent_v];
            }
        }
        self.parent[v] = parent_v;
        parent_v
    }
}

