    let i1 = if n < h { n } else { h - 1 };
    for i in i0..(i1+1) {
      let j = n - i;
      if i == 0 {
        memo[i][j] = memo[i][j-1] + (if map[i][j-1] == '.' && map[i][j] == '#' { 1 } else { 0 });
      } else if j == 0 {
        memo[i][j] = memo[i-1][j] + (if map[i-1][j] == '.' && map[i][j] == '#' { 1 } else { 0 });
