        else:
            x_list[x].append(y)
        if y_list[y] is None:
            y_list[y] = [x]
        else:
            y_list[y].append(x)

    visited = [False] * (N + 1)
    connections = [None] * (N + 1)
    for i in range(1, N + 1):
        if not visited[i]:
            q = []
            c = set()
            visited[i] = True
            q.append(i)
            while 0 < len(q):
                j = q.pop(0)
                c.add(j)
                if not x_list[j] is None:
                    for k in x_list[j]:
                        if not visited[k]:
                            visited[k] = True
                            q.append(k)
                if not y_list[j] is None:
                    for k in y_list[j]:
                        if not visited[k]:
                            visited[k] = True
                            q.append(k)
            if 1 < len(c):
                connections[i] = c

