fn modinv(a: i64, n: i64) -> i64 {
    let mut t = (0, 1);
    let mut r = (n, a);
    while r.1 != 0 {
        t = (t.1, t.0 - (r.0 / r.1) * t.1);
        r = (r.1, r.0 % r.1);
