use proconio::input;

const MOD:i64 = 1_000_000_007;

fn main() {
    input!{
        k:usize,
        s:String,
    };

    let n = s.len();

    let mut ans:i64 = 0;

    let mut fact = vec![1i64;n+k+1];
    for i in 0..n+k {
        fact[i+1] = fact[i]*((i+1) as i64)%MOD;
    }

    let powm = |mut x,mut k| {
        let mut res = 1;
        while k>0 {
            if k&1==1 {
                res = res*x%MOD;
            }
            k>>=1;
            x=x*x%MOD;
        }
        res
    };
    let mod_inv = |x| {
        powm(x,MOD-2)
    };
    let comb = |n,k| {
        fact[n] * mod_inv(fact[n-k]) %MOD * mod_inv(fact[k])%MOD
    };
    for i in 0..k {
        let pat = comb(n+k-i-1,n-1)*powm(25,(k-i) as i64)%MOD*powm(26,i as i64)%MOD;
        ans+=pat;
        ans%=MOD;
    }
    ans+=powm(26,k as i64);
    ans%=MOD;

    println!("{}",ans);






}

